package com.wipro.hibernate; import java.math.BigDecimal; import java.util.Date; public class Emp {private int empno;private String ename,job;private int mgr;private Date hiredate;private BigDecimal sal,comm;private int deptno; public Emp(){} public int getEmpno(){return empno;}public void setEmpno(int v){empno=v;}public String getEname(){return ename;}public void setEname(String v){ename=v;}public String getJob(){return job;}public void setJob(String v){job=v;}public int getMgr(){return mgr;}public void setMgr(int v){mgr=v;}public Date getHiredate(){return hiredate;}public void setHiredate(Date v){hiredate=v;}public BigDecimal getSal(){return sal;}public void setSal(BigDecimal v){sal=v;}public BigDecimal getComm(){return comm;}public void setComm(BigDecimal v){comm=v;}public int getDeptno(){return deptno;}public void setDeptno(int v){deptno=v;}}